insert into public.projects (slug, title, title_jp, kanji, tone, category, year, role, duration, summary, overview, challenge, approach, results, stack, links, cover_url, status) values
  ('minori-ai-rcr', 'Minori AI RCR', '採用AIシステム', '採', 'dark', 'AI Grading · Rekrutmen', '2026', 'Full-stack & AI Integration', '2 bulan', 'Website walk-in rekrutmen untuk PT Minori dengan AI yang menilai calon pemagang secara otomatis, jadi tim rekrutmen bisa langsung filter kandidat berdasarkan grade.', 'Minori AI RCR adalah website walk-in rekrutmen untuk calon pemagang di PT Minori. Peserta mendaftar dan mengisi biodata langsung di website, lalu mengerjakan tes. Di dalam sistemnya saya integrasikan AI yang mengolah biodata dan hasil tes tiap peserta menjadi satu grade. Dari dashboard, tim rekrutmen tinggal filter dan urutkan kandidat berdasarkan grade, gak perlu cek satu per satu lagi.', 'Saat walk-in, pendaftar bisa datang banyak dalam waktu singkat. Menilai biodata dan hasil tes satu per satu itu makan waktu, dan hasilnya bisa beda-beda tergantung siapa yang menilai. Sistemnya harus memberi penilaian yang konsisten untuk semua peserta dan tetap mudah dipahami tim rekrutmen.', '["Membangun alur walk-in di website: pendaftaran, pengisian biodata, sampai tes peserta dalam satu tempat.","Menyusun kriteria penilaian dari biodata dan hasil tes, lalu menerjemahkannya jadi instruksi yang dipakai AI saat memberi grade.","Mengintegrasikan AI ke dalam sistem supaya grade tiap peserta dihitung otomatis setelah tes selesai.","Membuat dashboard rekrutmen untuk memfilter, mengurutkan, dan melihat detail kandidat berdasarkan grade."]'::jsonb, '[{"value":"Otomatis","label":"Grading dari biodata & hasil tes"},{"value":"Grade","label":"Jadi dasar filter kandidat"},{"value":"1 sistem","label":"Daftar, tes, dan penilaian dalam satu website"}]'::jsonb, array['Laravel', 'React', 'Integrasi LLM', 'FastAPI', 'MySQL']::text[], '{}'::jsonb, null, 'Terbit');
